def populate_headers(headers):
    """
    Concatenate headers with subheaders
    """
    headers_dict = {}
    for header in headers:
        headers_dict[header] = {}
        for subheader in header.subheaders:
            headers_dict[header][subheader] = []

    return headers_dict

